const rotateSession = `-- name: RotateSession :one
UPDATE user_sessions
SET token_hash = $1, csrf_secret = $2, auth_epoch = $3
WHERE id = $4 AND user_id = $5 AND revoked_at IS NULL
RETURNING expires_at
`

type RotateSessionParams struct {
	TokenHash  []byte
	CsrfSecret []byte
	AuthEpoch  int32
	ID         uuid.UUID
	UserID     uuid.UUID
}

// Gives a live session a new token and CSRF secret under the current auth epoch (after a
// password change), so a previously copied token stops working while the user stays
// signed in. Returns the unchanged absolute expiry for the new cookie.
func (q *Queries) RotateSession(ctx context.Context, arg RotateSessionParams) (time.Time, error) {
	row := q.db.QueryRow(ctx, rotateSession,
		arg.TokenHash,
		arg.CsrfSecret,
		arg.AuthEpoch,
		arg.ID,
		arg.UserID,
	)
	var expires_at time.Time
	err := row.Scan(&expires_at)
	return expires_at, err
}

const touchSession = `-- name: TouchSession :execrows
UPDATE user_sessions
SET last_seen_at = $1, idle_expires_at = LEAST($2, expires_at)
WHERE id = $3
  AND revoked_at IS NULL
  AND idle_expires_at > $1
  AND expires_at > $1
`

type TouchSessionParams struct {
	Now           time.Time
	IdleExpiresAt time.Time
	ID            uuid.UUID
}

// Slides the idle timeout of a still-live session; never revives an expired one and
// never extends past the absolute expiry. Callers throttle this to avoid a write per request.
func (q *Queries) TouchSession(ctx context.Context, arg TouchSessionParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchSession, arg.Now, arg.IdleExpiresAt, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateUserProfile = `-- name: UpdateUserProfile :execrows
UPDATE users
SET display_name = $1, username = $2, bio = $3,
    experience_level = $4, locale = $5, timezone = $6,
    unit_prefs = $7, notification_prefs = $8,
    updated_at = $9, version = version + 1
WHERE id = $10 AND version = $11 AND status = 'active'
`

type UpdateUserProfileParams struct {
	DisplayName       string
	Username          *string
	Bio               *string
	ExperienceLevel   *string
	Locale            string
	Timezone          string
	UnitPrefs         json.RawMessage
	NotificationPrefs json.RawMessage
	Now               time.Time
	ID                uuid.UUID
	Version           int32
}

// Optimistic lock: 0 rows means the version is stale (or the account is gone).
func (q *Queries) UpdateUserProfile(ctx context.Context, arg UpdateUserProfileParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateUserProfile,
		arg.DisplayName,
		arg.Username,
		arg.Bio,
		arg.ExperienceLevel,
		arg.Locale,
		arg.Timezone,
		arg.UnitPrefs,
		arg.NotificationPrefs,
		arg.Now,
		arg.ID,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
